// PointerEvent.altitudeAngle getter: readonly attribute double altitudeAngle; RV_ERR_UNSUPPORTED while the setting AltitudeAngleEnabled is off
int32_t ranvier_dom_pointer_event_get_altitude_angle(RvEvent* target, double* result)
{
    if (!target || !result)
        return RV_ERR_NULL_ARGUMENT;
    if (!isMainThread())
        return RV_ERR_WRONG_THREAD;
    RefPtr impl = dynamicDowncast<PointerEvent>(*eventOf(target));
    if (!impl)
        return RV_ERR_WRONG_INTERFACE;
    RefPtr settingsNode = dynamicDowncast<Node>(impl->target());
    if (!settingsNode)
        return RV_ERR_UNSUPPORTED;
    auto& settings = settingsNode->document().settingsValues();
    if (!(settings.altitudeAngleEnabled))
        return RV_ERR_UNSUPPORTED;
    return deliver([&]() -> decltype(auto) { return impl->altitudeAngle(); }, [&](auto&& value) { return store<double>(value, result); });
}

